#!/usr/bin/env python3
"""Bump Homebrew casks and formulae in this tap to their source repo's latest release.

For every file in ``Casks/*.rb`` and ``Formula/*.rb`` the script:

1. skips generated files that carry a release hook (GoReleaser writes them),
2. reads the current version,
3. resolves the ``owner/repo`` whose GitHub releases the file downloads from,
4. asks the GitHub API for the latest release,
5. maps every sha256 in the file to an asset of the *old* release by digest,
6. downloads and verifies each new asset (digest, ``checksums.txt``, build
   attestation),
7. checks that every literal ``binary``/``artifact`` path exists in the
   tarball (casks only),
8. rewrites the file and runs ``brew style`` on it,
9. unless ``--dry-run``: pushes ``bump/<token>-<new>`` and opens one PR into
   the base ref.

The script never pushes to the base ref itself. It needs the ``gh`` CLI, ``git``
and ``brew`` on PATH. Only the Python standard library is used otherwise.
"""

from __future__ import annotations

import argparse
import difflib
import hashlib
import json
import os
import re
import subprocess
import sys
import tarfile
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Callable, Iterable, Mapping

GENERATED_MARKER = "This file was generated by GoReleaser"
TAP_SLUG = "frostyard/homebrew-tap"

SHA256_RE = re.compile(r"\b([0-9a-fA-F]{64})\b")
SOURCE_URL_RE = re.compile(
    r"https://github\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+)/releases/download/"
)
VERSION_LINE_RE = re.compile(r'^(\s*version\s+")([^"]+)(".*)$')
URL_LINE_RE = re.compile(r"^(\s*url\s+\")([^\"]+)(\".*)$")
BINARY_LINE_RE = re.compile(r'^\s*(?:binary|artifact)\s+"([^"]+)"')
TAG_VERSION_RE = re.compile(r"/releases/download/v?([^/]+)/")

STATUS_OK = {"current", "release-hook", "unsupported", "pr-exists", "verified", "bumped"}


class BumpError(Exception):
    """A fail-closed problem with one item."""


# --------------------------------------------------------------------------- #
# Small helpers
# --------------------------------------------------------------------------- #


def parse_version(text: str) -> tuple[int, ...]:
    """Return the numeric dotted parts of a version string, as a tuple."""
    parts = [int(p) for p in re.findall(r"\d+", text)]
    while len(parts) > 1 and parts[-1] == 0:
        del parts[-1]
    return tuple(parts) if parts else (0,)


def version_less(left: str, right: str) -> bool:
    """Report whether version ``left`` is older than version ``right``."""
    return parse_version(left) < parse_version(right)


def replace_version(text: str, old: str, new: str) -> str:
    """Replace ``old`` with ``new`` where it is a whole dotted version token."""
    pattern = re.compile(r"(?<![0-9.])" + re.escape(old) + r"(?![0-9.])")
    return pattern.sub(new, text)


def sha256_file(path: Path) -> str:
    """Return the hex sha256 of a file."""
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def strip_digest(digest: str) -> str:
    """Return the hex part of a GitHub ``sha256:<hex>`` asset digest."""
    return digest.split(":", 1)[1].lower() if digest else ""


def asset_index(release: Mapping) -> dict[str, Mapping]:
    """Map asset name to asset record for one release payload."""
    return {asset.get("name", ""): asset for asset in release.get("assets") or []}


# --------------------------------------------------------------------------- #
# The gh CLI layer (faked in the unit tests)
# --------------------------------------------------------------------------- #


class GhClient:
    """Thin wrapper around the ``gh`` CLI: releases, downloads, attestations."""

    def __init__(self, runner: Callable[[list[str]], str] | None = None) -> None:
        self._runner = runner or _run
        self._cache: dict[tuple[str, str | None], Mapping | None] = {}

    def release(self, slug: str, tag: str | None = None) -> Mapping | None:
        """Return a release payload, or ``None`` when the release is absent."""
        key = (slug, tag)
        if key in self._cache:
            return self._cache[key]
        endpoint = f"repos/{slug}/releases/latest" if tag is None else f"repos/{slug}/releases/tags/{tag}"
        try:
            payload = json.loads(self._runner(["gh", "api", endpoint]))
        except RuntimeError:
            payload = None
        self._cache[key] = payload
        return payload

    def download(self, slug: str, tag: str, name: str, dest: Path) -> Path:
        """Download one release asset into ``dest`` and return its path."""
        self._runner(
            [
                "gh",
                "release",
                "download",
                tag,
                "--repo",
                slug,
                "--pattern",
                name,
                "--dir",
                str(dest),
                "--clobber",
            ]
        )
        path = dest / name
        if not path.is_file():
            raise BumpError(f"download of {name} produced no file")
        return path

    def open_pr(self, slug: str, head: str) -> str | None:
        """Return the number of an open PR whose head is ``head``, if any."""
        try:
            payload = self._runner(
                ["gh", "pr", "list", "--repo", slug, "--head", head, "--state", "open", "--json", "number"]
            )
            pulls = json.loads(payload or "[]")
        except (RuntimeError, json.JSONDecodeError):
            return None
        return str(pulls[0]["number"]) if pulls else None

    def create_pr(self, slug: str, base: str, head: str, title: str, body: str) -> str:
        """Open a pull request and return its URL; raise ``RuntimeError`` on failure."""
        return self._runner(
            [
                "gh",
                "pr",
                "create",
                "--repo",
                slug,
                "--base",
                base,
                "--head",
                head,
                "--title",
                title,
                "--body",
                body,
            ]
        ).strip()

    def verify_attestation(self, path: Path, slug: str) -> None:
        """Raise ``BumpError`` unless ``gh attestation verify`` exits 0."""
        try:
            self._runner(["gh", "attestation", "verify", str(path), "--repo", slug])
        except RuntimeError as error:
            raise BumpError(f"build attestation of {path.name} does not verify: {error}") from error


def _run(argv: list[str]) -> str:
    """Run a command and return its stdout; raise ``RuntimeError`` on failure."""
    result = subprocess.run(argv, capture_output=True, text=True, check=False)
    if result.returncode != 0:
        message = (result.stderr or result.stdout or "").strip().splitlines()
        raise RuntimeError(message[-1] if message else f"{argv[0]} exited {result.returncode}")
    return result.stdout


def brew_style(path: Path) -> None:
    """Run ``brew style`` on one file; raise ``BumpError`` on failure."""
    try:
        _run(["brew", "style", str(path)])
    except FileNotFoundError as error:
        raise BumpError(f"brew is not installed: {error}") from error
    except RuntimeError as error:
        raise BumpError(f"brew style failed: {error}") from error


def _git(argv: list[str], cwd: Path) -> str:
    """Run git in ``cwd`` and return stdout."""
    return _run(["git", "-C", str(cwd), *argv])


# --------------------------------------------------------------------------- #
# Result rows and the item pipeline
# --------------------------------------------------------------------------- #


@dataclass
class ItemResult:
    """One row of the summary table."""

    item: str
    status: str
    current: str = ""
    latest: str = ""
    detail: str = ""

    @property
    def failed(self) -> bool:
        """Report whether the row makes the run fail."""
        return self.status not in STATUS_OK


@dataclass
class Bumper:
    """Configuration for one run."""

    tap_dir: Path
    base_ref: str
    dry_run: bool
    gh: GhClient
    tap_slug: str = TAP_SLUG
    style: Callable[[Path], None] = brew_style
    git: Callable[[list[str], Path], str] = _git
    start_ref: str = ""


def source_slug(text: str) -> str | None:
    """Return ``owner/repo`` for the release URL(s) in a file, or ``None``."""
    slugs = {f"{m.group(1)}/{m.group(2)}" for m in SOURCE_URL_RE.finditer(text)}
    if not slugs:
        return None
    if len(slugs) > 1:
        raise BumpError(f"downloads from more than one repo: {', '.join(sorted(slugs))}")
    return slugs.pop()


def current_version(text: str) -> str | None:
    """Return the version a cask states, or the one in a formula's url."""
    for line in text.splitlines():
        match = VERSION_LINE_RE.match(line)
        if match:
            return match.group(2)
    for line in text.splitlines():
        if URL_LINE_RE.match(line):
            match = TAG_VERSION_RE.search(line)
            if match:
                return match.group(1)
    return None


def cask_hashes(text: str) -> list[str]:
    """Return every sha256 of a ``sha256`` stanza, lowercased.

    A stanza can continue on following lines (``sha256 arm64_linux: "…",`` then
    ``x86_64_linux: "…"``), so a line that carries an arch label continues the
    stanza started by the preceding ``sha256`` line.
    """
    hashes: list[str] = []
    in_stanza = False
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.startswith("sha256"):
            in_stanza = True
        elif not (in_stanza and re.match(r'^[A-Za-z0-9_]+:\s*"', stripped)):
            in_stanza = False
        if not in_stanza:
            continue
        hashes.extend(hexdigest.lower() for hexdigest in SHA256_RE.findall(line))
        if not stripped.endswith(","):
            in_stanza = False
    return hashes


def literal_artifacts(text: str) -> list[str]:
    """Return the literal ``binary``/``artifact`` paths of a cask."""
    paths = []
    for line in text.splitlines():
        match = BINARY_LINE_RE.match(line)
        if match and "#{" not in match.group(1):
            paths.append(match.group(1))
    return paths


def tarball_members(path: Path) -> set[str]:
    """Return the member names of a tarball, with ``./`` stripped."""
    with tarfile.open(path) as archive:
        return {name[2:] if name.startswith("./") else name for name in archive.getnames()}


def artifact_present(artifact: str, members: Iterable[str]) -> bool:
    """Report whether a cask artifact exists in a tarball."""
    return any(member == artifact or member.endswith("/" + artifact) for member in members)


def edit_text(text: str, hash_map: Mapping[str, str], old_version: str, new_version: str) -> str:
    """Return the file text with new hashes and the new version."""
    lines = []
    for line in text.splitlines(keepends=True):
        for old_hash, new_hash in hash_map.items():
            line = line.replace(old_hash, new_hash)
        match = VERSION_LINE_RE.match(line) or URL_LINE_RE.match(line)
        if match and old_version != new_version:
            line = replace_version(line, old_version, new_version)
        lines.append(line)
    return "".join(lines)


def new_asset_name(old_name: str, old_version: str, new_version: str) -> str:
    """Return the new asset name: the old name with its version replaced."""
    return replace_version(old_name, old_version, new_version)


def verify_asset(
    bumper: Bumper,
    slug: str,
    tag: str,
    name: str,
    expected_sha: str,
    checksums: Mapping[str, str] | None,
    dest: Path,
) -> Path:
    """Download and verify one new asset; return its path."""
    path = bumper.gh.download(slug, tag, name, dest)
    actual = sha256_file(path)
    if actual != expected_sha:
        raise BumpError(f"{name}: sha256 {actual} differs from release digest {expected_sha}")
    if checksums is not None:
        listed = checksums.get(name)
        if listed is None:
            raise BumpError(f"checksums.txt of {tag} has no line for {name}")
        if listed != expected_sha:
            raise BumpError(f"checksums.txt lists {listed} for {name}, release digest is {expected_sha}")
    bumper.gh.verify_attestation(path, slug)
    return path


def fetch_checksums(bumper: Bumper, slug: str, tag: str, assets: Mapping[str, Mapping], dest: Path) -> dict[str, str] | None:
    """Return ``{asset name: sha256}`` from the release's checksums.txt, if any."""
    if "checksums.txt" not in assets:
        return None
    path = bumper.gh.download(slug, tag, "checksums.txt", dest)
    table: dict[str, str] = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        parts = line.split()
        if len(parts) == 2 and re.fullmatch(r"[0-9a-fA-F]{64}", parts[0]):
            table[parts[1].lstrip("*")] = parts[0].lower()
    return table


def tap_start_ref(bumper: Bumper) -> str:
    """Return the tap's ref at the start of the run, resolved once."""
    if bumper.start_ref:
        return bumper.start_ref
    head = bumper.git(["rev-parse", "--abbrev-ref", "HEAD"], bumper.tap_dir).strip()
    if head and head != "HEAD":
        bumper.start_ref = head
    else:
        bumper.start_ref = bumper.git(["rev-parse", "HEAD"], bumper.tap_dir).strip()
    return bumper.start_ref


def restore_tap(bumper: Bumper) -> None:
    """Return the tap to its starting ref with a clean work tree."""
    start = tap_start_ref(bumper)
    bumper.git(["checkout", "--force", start], bumper.tap_dir)
    bumper.git(["reset", "--hard", start], bumper.tap_dir)


def branch_exists(bumper: Bumper, branch: str) -> bool:
    """Report whether ``branch`` exists on the remote."""
    try:
        bumper.git(["ls-remote", "--exit-code", "--heads", "origin", branch], bumper.tap_dir)
    except RuntimeError:
        return False
    return True


def bump_item(bumper: Bumper, path: Path, kind: str) -> ItemResult:
    """Process one cask or formula file."""
    item = path.stem
    text = path.read_text(encoding="utf-8")
    first_line = text.splitlines()[0] if text.splitlines() else ""
    if GENERATED_MARKER in first_line:
        return ItemResult(item=item, status="release-hook", detail="generated on release; not bumped here")

    slug = source_slug(text)
    if slug is None:
        return ItemResult(item=item, status="unsupported", detail="no GitHub release download URL")

    version = current_version(text)
    if version is None:
        raise BumpError("no version line and no version in the url")

    latest_payload = bumper.gh.release(slug)
    if not latest_payload:
        raise BumpError(f"cannot read the latest release of {slug}")
    tag = latest_payload.get("tag_name", "")
    latest = tag[1:] if tag.startswith("v") else tag
    if not latest:
        raise BumpError(f"latest release of {slug} has no tag name")
    if latest == version or not version_less(version, latest):
        return ItemResult(item=item, status="current", current=version, latest=latest)

    old_payload = bumper.gh.release(slug, f"v{version}") or bumper.gh.release(slug, version)
    if not old_payload:
        raise BumpError(f"cannot read release v{version} of {slug} to map the sha256 values")
    old_assets = asset_index(old_payload)
    by_digest = {strip_digest(asset.get("digest", "")): asset for asset in old_assets.values() if asset.get("digest")}

    hashes = cask_hashes(text)
    if not hashes:
        raise BumpError("no sha256 found in the file")
    hash_map: dict[str, str] = {}
    new_names: list[str] = []
    for old_hash in hashes:
        old_asset = by_digest.get(old_hash)
        if old_asset is None:
            raise BumpError(f"cannot map sha256 {old_hash} to an asset of v{version}")
        new_names.append(new_asset_name(old_asset["name"], version, latest))
    new_assets = asset_index(latest_payload)
    missing = [name for name in new_names if name not in new_assets]
    if missing:
        raise BumpError(f"{tag} has no asset {', '.join(missing)}")

    with tempfile.TemporaryDirectory(prefix="bump-") as work:
        work_dir = Path(work)
        checksums = fetch_checksums(bumper, slug, tag, new_assets, work_dir)
        for old_hash, name in zip(hashes, new_names):
            expected = strip_digest(new_assets[name].get("digest", ""))
            if not expected:
                raise BumpError(f"{name}: {tag} publishes no digest")
            hash_map[old_hash] = expected
            path_on_disk = verify_asset(bumper, slug, tag, name, expected, checksums, work_dir)
            if kind == "cask" and name.endswith((".tar.gz", ".tgz")):
                members = tarball_members(path_on_disk)
                for artifact in literal_artifacts(text):
                    if not artifact_present(artifact, members):
                        raise BumpError(f"{name} does not contain {artifact}")

    edited = edit_text(text, hash_map, version, latest)
    path.write_text(edited, encoding="utf-8")
    try:
        bumper.style(path)
    except BumpError as error:
        path.write_text(text, encoding="utf-8")
        raise BumpError(str(error)) from error

    if bumper.dry_run:
        diff = "".join(
            difflib.unified_diff(
                text.splitlines(keepends=True),
                edited.splitlines(keepends=True),
                fromfile=f"a/{path.name}",
                tofile=f"b/{path.name}",
            )
        )
        print(diff, end="")
        restore_tap(bumper)
        return ItemResult(item=item, status="verified", current=version, latest=latest, detail="dry run; file restored")

    return publish(bumper, path, kind, item, version, latest, hash_map)


def publish(
    bumper: Bumper,
    path: Path,
    kind: str,
    item: str,
    old_version: str,
    new_version: str,
    hash_map: Mapping[str, str],
) -> ItemResult:
    """Commit the edited file on a bump branch, push it, and open one PR.

    Every bump branch starts at the tap's starting ref, never at another item's
    bump branch, and the tap is back on that ref with a clean work tree before
    the function returns — on success, on a push failure and on a PR failure.
    """
    branch = f"bump/{item}-{new_version}"
    relative = str(path.relative_to(bumper.tap_dir))
    start = tap_start_ref(bumper)
    if branch_exists(bumper, branch) or bumper.gh.open_pr(bumper.tap_slug, branch):
        restore_tap(bumper)
        return ItemResult(item=item, status="pr-exists", current=old_version, latest=new_version, detail=branch)

    prefix = "fix(cask)" if kind == "cask" else "fix(formula)"
    subject = f"{prefix}: bump {item} to v{new_version}"
    try:
        bumper.git(["checkout", "-B", branch, start], bumper.tap_dir)
        bumper.git(["add", relative], bumper.tap_dir)
        bumper.git(["commit", "-m", subject], bumper.tap_dir)
        bumper.git(["push", "--set-upstream", "origin", branch], bumper.tap_dir)
    except RuntimeError as error:
        restore_tap(bumper)
        raise BumpError(f"cannot push {branch}: {error}") from error

    body = pr_body(item, kind, old_version, new_version, hash_map)
    try:
        url = bumper.gh.create_pr(bumper.tap_slug, bumper.base_ref, branch, subject, body)
    except RuntimeError as error:
        restore_tap(bumper)
        return ItemResult(
            item=item,
            status="pr-failed",
            current=old_version,
            latest=new_version,
            detail=(
                f"branch {branch} is pushed, PR creation failed: {error}. "
                "Brian: allow GitHub Actions to create pull requests"
            ),
        )
    restore_tap(bumper)
    return ItemResult(
        item=item,
        status="bumped",
        current=old_version,
        latest=new_version,
        detail=f"PR into {bumper.base_ref}: {url}",
    )


def pr_body(item: str, kind: str, old_version: str, new_version: str, hash_map: Mapping[str, str]) -> str:
    """Return the pull request body for one bump."""
    rows = "\n".join(f"| `{old}` | `{new}` |" for old, new in hash_map.items())
    return (
        f"Bumps the {kind} `{item}` from `{old_version}` to `{new_version}`.\n\n"
        "Every new asset was verified before this PR was opened:\n\n"
        "1. the sha256 computed from the downloaded asset equals the asset's GitHub release digest,\n"
        "2. the value equals the line for the asset in the release's `checksums.txt`,\n"
        "3. `gh attestation verify` accepts the asset's build provenance.\n\n"
        "| Old sha256 | New sha256 |\n| --- | --- |\n"
        f"{rows}\n\n"
        "Opened by `.github/workflows/bump.yml` (`.github/scripts/bump_casks.py`). "
        "The workflow never pushes to `main`; please review and merge.\n"
    )


# --------------------------------------------------------------------------- #
# Reporting and entry point
# --------------------------------------------------------------------------- #


def summary_table(results: list[ItemResult]) -> str:
    """Return the Markdown table for the step summary."""
    lines = ["| Item | Status | Current | Latest | Detail |", "| --- | --- | --- | --- | --- |"]
    for result in results:
        detail = result.detail.replace("|", "\\|").replace("\n", " ")
        lines.append(f"| `{result.item}` | {result.status} | {result.current} | {result.latest} | {detail} |")
    return "\n".join(lines) + "\n"


def collect_items(tap_dir: Path) -> list[tuple[Path, str]]:
    """Return every cask and formula file with its kind."""
    items: list[tuple[Path, str]] = []
    for directory, kind in (("Casks", "cask"), ("Formula", "formula")):
        for path in sorted((tap_dir / directory).glob("*.rb")):
            items.append((path, kind))
    return items


def main(argv: list[str] | None = None) -> int:
    """Run the bump over the tap and report the exit status."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--tap-dir", default="tap", help="checkout of the tap to inspect and edit")
    parser.add_argument("--base-ref", default="main", help="branch to check and the PR base")
    parser.add_argument("--dry-run", action="store_true", help="do not push or open pull requests")
    parser.add_argument("--item", action="append", help="only process this cask or formula name")
    args = parser.parse_args(argv)

    tap_dir = Path(args.tap_dir).resolve()
    items = collect_items(tap_dir)
    if args.item:
        wanted = set(args.item)
        items = [entry for entry in items if entry[0].stem in wanted]
    if not items:
        print("no cask or formula files found", file=sys.stderr)
        return 1

    bumper = Bumper(tap_dir=tap_dir, base_ref=args.base_ref, dry_run=args.dry_run, gh=GhClient())
    results: list[ItemResult] = []
    for path, kind in items:
        try:
            result = bump_item(bumper, path, kind)
        except BumpError as error:
            result = ItemResult(item=path.stem, status="error", detail=str(error))
        except RuntimeError as error:
            result = ItemResult(item=path.stem, status="error", detail=str(error))
        results.append(result)
        print(f"{result.item}: {result.status} {result.detail}".rstrip())

    table = summary_table(results)
    summary_path = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary_path:
        with Path(summary_path).open("a", encoding="utf-8") as handle:
            handle.write(table)
    else:
        print(table)

    return 1 if any(result.failed for result in results) else 0


if __name__ == "__main__":
    sys.exit(main())
